n9=A.c0(i7,B.m7,"\u062e\u0637\u0647 \u0627\u0646\u062c\u0627\u0632 \u062a\u062b\u0628\u064a\u062a \u0645\u0631\u0628\u0639\u0627\u062a \u0634\u0628\u0643\u0647",A.a_f(new A.d8t()),n9,i5,B.D,"\u0634\u0628\u0643\u0629 \u0627\u0644\u062e\u0637\u0629: \u0645\u0627 \u0623\u0646\u062c\u0632\u0647 \u0643\u0644 \u0637\u0627\u0644\u0628 \u0645\u0646\u0647\u0627",i6,"\u062e\u0637\u0629 \u0627\u0644\u0625\u0646\u062c\u0627\u0632 \u0644\u062d\u0644\u0642\u062a\u064a",A.rY())
s=A.a(["\u0627\u0644\u0637\u0644\u0628\u0629","\u22ee \u0627\u0644\u0645\u0632\u064a\u062f","\u0633\u062c\u0644\u0651 \u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631\u0627\u062a"],m9)
